class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = Object.assign({ q: '', country: '', share: '', sort: '', cur: '', sea: false, ready: false, view: 'list', more: false, sel: [], open: '', focus: '', helpOpen: false, whyOpen: false, whyId: '', pickOpen: false, pickId: '', newOn: false, newTitle: '', newClient: '', pickErr: false, eT: false, eC: false, toast: '', extra: [] }, {});
  }
  componentDidMount() {
    this._k = (e) => { if (e.key === 'Escape') this.setState({ whyOpen: false, pickOpen: false, open: '' }); };
    document.addEventListener('keydown', this._k);
  }
  componentWillUnmount() { document.removeEventListener('keydown', this._k); clearTimeout(this._tm); }
  say(t) { this.setState({ toast: t }); clearTimeout(this._tm); this._tm = setTimeout(() => this.setState({ toast: '' }), 4200); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o), NB = ' ';
    const fm = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, NB);
    const RATE = { AED: 3.67, THB: 34.5, EUR: 0.93, USD: 1 };
    const price = (o, usd) => { const c = usd ? 'USD' : o.cur, v = usd ? o.price / RATE[o.cur] : o.price; return fm(v) + NB + c; };
    const word = (n, a, b, c) => { const m = n % 10, h = n % 100; return n + ' ' + (m === 1 && h !== 11 ? a : (m >= 2 && m <= 4 && (h < 10 || h >= 20) ? b : c)); };
    const D = [
      { id: 'creek', name: 'Creek Residence', city: 'Дубай', co: 'ОАЭ', st: 'build', when: 'Сдача в 2027', kind: 'Апартаменты, 1-3 спальни', price: 1450000, cur: 'AED', dc: 5, sea: false, x: 66, y: 52 },
      { id: 'marina', name: 'Marina Shore', city: 'Дубай', co: 'ОАЭ', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, 1-2 спальни', price: 1180000, cur: 'AED', dc: 7, sea: true, x: 63, y: 55 },
      { id: 'limassol', name: 'Limassol Gardens', city: 'Лимассол', co: 'Республика Кипр', coS: 'Кипр', st: 'build', when: 'Сдача в 2028', kind: 'Апартаменты, 2-3 спальни', price: 310000, cur: 'EUR', dc: 0, sea: true, x: 40, y: 46 },
      { id: 'batumi', name: 'Batumi Sea Tower', city: 'Батуми', co: 'Грузия', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, студии и 1 спальня', price: 115000, cur: 'USD', dc: 5, sea: true, x: 50, y: 20 },
      { id: 'antalya', name: 'Antalya Hills', city: 'Анталья', co: 'Турция', st: 'build', when: 'Сдача в 2027', kind: 'Вилла, 3-4 спальни', price: 165000, cur: 'USD', dc: 7, sea: false, x: 33, y: 36 },
      { id: 'rawai', name: 'Proud Rawai Resort', city: 'Пхукет', co: 'Таиланд', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, 1-2 спальни', price: 3526000, cur: 'THB', dc: 7, sea: true, x: 86, y: 80 },
      { id: 'mira', name: 'Mira Coral Bay', city: 'Рас-эль-Хайма', co: 'ОАЭ', st: 'build', when: 'Сдача в 2028', kind: 'Апартаменты, 1-3 спальни', price: 555000, cur: 'AED', dc: 0, sea: true, x: 69, y: 47 },
      { id: 'beverly', name: 'Beverly mountain Bay', city: 'Паттайя', co: 'Таиланд', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, студии и 2 спальни', price: 3195000, cur: 'THB', dc: 5, sea: false, x: 90, y: 70 },
      { id: 'serene', name: 'Serene Raya Villas Bangjo', city: 'Пхукет', co: 'Таиланд', st: 'build', when: 'Сдача в 2027', kind: 'Вилла, 3-4 спальни', price: 22500000, cur: 'THB', dc: 7, sea: false, x: 83, y: 84 },
      { id: 'zenith', name: 'Zenith Pattaya II', city: 'Паттайя', co: 'Таиланд', st: 'plan', when: 'Сроки сдачи пока не названы', kind: 'Апартаменты, студии и 3 спальни', price: 3840000, cur: 'THB', dc: 5, sea: false, x: 93, y: 66 },
      { id: 'skypark', name: 'Skypark Celeste', city: 'Пхукет', co: 'Таиланд', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, 1 спальня', price: 5400000, cur: 'THB', dc: 7, sea: false, x: 89, y: 78 },
      { id: 'tersane', name: 'Tersane Istanbul', city: 'Стамбул', co: 'Турция', st: 'build', when: 'Сдача в 2028', kind: 'Апартаменты, 1-3 спальни', price: 1125000, cur: 'USD', dc: 0, sea: true, x: 26, y: 24 }
    ];
    D.forEach((o) => { o.sh = o.dc ? [o.dc * 0.1, o.dc * 0.45] : null; });
    const pc = (x) => String(+x.toFixed(2)).replace('.', ',');
    const ST = { ready: ['ГОТОВ', 'badge--ok'], build: ['СТРОИТСЯ', ''], plan: ['ПЛАНИРУЕТСЯ', 'badge--muted'] };
    const usdOf = (o) => o.price / RATE[o.cur];
    const COUNTRIES = ['ОАЭ', 'Таиланд', 'Республика Кипр', 'Грузия', 'Турция'];
    /* поиск словами */
    const SYN = { 'квартир': 'апартамент', 'дом': 'вилла', 'морем': 'море', 'моря': 'море', 'море': 'море' };
    let q = S.q.toLowerCase(), cap = null;
    const mb = q.match(/до\s*(\d+(?:[.,]\d+)?)\s*(млн|тыс)?/);
    if (mb) { cap = parseFloat(mb[1].replace(',', '.')) * (mb[2] === 'млн' ? 1e6 : mb[2] === 'тыс' ? 1e3 : 1); q = q.replace(mb[0], ' '); }
    const toks = q.split(/[^a-zа-яё0-9]+/).filter((t) => t.length > 2 && t !== 'для');
    const hay = (o) => (o.name + ' ' + o.city + ' ' + o.co + ' ' + o.kind + ' ' + (o.sea ? 'море у моря' : '') + ' ' + (o.st === 'ready' ? 'готов сейчас' : '')).toLowerCase().replace('апартаменты', 'апартамент квартира').replace('вилла', 'вилла дом');
    let list = D.concat(S.extra).filter((o) => {
      if (S.country && o.co !== S.country) return false;
      if (S.share && !(o.sh && o.sh[1] >= +S.share)) return false;
      if (S.sea && !o.sea) return false;
      if (S.ready && o.st !== 'ready') return false;
      if (cap && usdOf(o) > cap * (cap < 5000 ? 1 : 1)) return false;
      const h = hay(o);
      return toks.every((t) => h.indexOf(t.slice(0, Math.max(4, t.length - 2))) >= 0);
    });
    if (S.sort === 'share') list = list.slice().sort((a, b) => (b.sh ? b.sh[1] : -1) - (a.sh ? a.sh[1] : -1));
    if (S.sort === 'cheap') list = list.slice().sort((a, b) => usdOf(a) - usdOf(b));
    const usd = S.cur === 'USD';
    const selSet = {}; S.sel.forEach((i) => { selSet[i] = 1; });
    const toggle = (id) => () => set({ sel: selSet[id] ? S.sel.filter((x) => x !== id) : S.sel.concat(id) });
    const shown = (S.more || list.length <= 6) ? list : list.slice(0, 6);
    const hrefOf = (o) => 'obekty-obekt.dc.html#' + o.id;
    const cards = shown.map((o) => ({
      name: o.name, href: hrefOf(o), where: o.city + ', ' + (o.coS || o.co), when: o.when, kind: o.kind, price: price(o, usd),
      tag: ST[o.st][0], tagCls: ST[o.st][1], hasShare: !!o.sh, noShare: !o.sh, share: o.sh ? pc(o.sh[1]) + '%' : '', openWhy: () => set({ whyOpen: true, whyId: o.id }),
      on: !!selSet[o.id], selCls: selSet[o.id] ? 'is-sel' : '', pickT: selSet[o.id] ? 'Выбрано' : 'Выбрать',
      pickAria: (selSet[o.id] ? 'Снять выбор: ' : 'Выбрать: ') + o.name, toggle: toggle(o.id)
    }));
    const wo = D.filter((x) => x.id === S.whyId)[0], wk = wo ? wo.dc : 0, wv = (r) => r == null ? '-' : pc(r * wk / 100) + '%';
    const WR = [['Холодная база', 10, null, null], ['Запрос', null, 20, 25], ['Выбрана страна', 30, 35, 40], ['Выбран проект', 30, 40, 45]].map((r) => ({ t: r[0], c: wv(r[1]), w: wv(r[2]), h: wv(r[3]) }));
    /* выпадающие списки */
    const mk = (id, title, opts, cur) => {
      const o = opts.filter((x) => x.v === cur)[0] || opts[0];
      return { title: title, open: S.open === id, isOpen: S.open === id, label: o.t, toggle: () => set({ open: S.open === id ? '' : id }),
        list: opts.map((x) => ({ t: x.t, sel: x.v === cur, cur: x.v === cur ? 'is-act' : '', pick: () => set({ [id]: x.v, open: '', more: false }) })) };
    };
    const selects = [
      mk('country', 'Страна', [{ v: '', t: 'Все страны' }].concat(COUNTRIES.map((c) => ({ v: c, t: c === 'Республика Кипр' ? 'Кипр' : c }))), S.country),
      mk('share', 'Ваша доля', [{ v: '', t: 'Любая' }, { v: '2', t: 'от 2%' }, { v: '3', t: 'от 3%' }], S.share),
      mk('sort', 'Порядок', [{ v: '', t: 'Как в каталоге' }, { v: 'share', t: 'Большая доля' }, { v: 'cheap', t: 'Дешевле' }], S.sort),
      mk('cur', 'Цены', [{ v: '', t: 'Как указано' }, { v: 'USD', t: 'В долларах' }], S.cur)
    ];
    const chips = [
      { t: 'Готово к заселению', on: !!S.ready, toggle: () => set({ ready: !S.ready, more: false }) },
      { t: 'Вид на море', on: !!S.sea, toggle: () => set({ sea: !S.sea, more: false }) }
    ];
    const dirty = !!(S.q || S.country || S.share || S.sort || S.cur || S.sea || S.ready);
    /* карта */
    const fo = list.filter((o) => o.id === S.focus)[0];
    const pins = list.map((o) => ({ label: o.name + ', ' + o.city, cls: o.id === S.focus ? 'is-on' : (selSet[o.id] ? 'is-sel' : ''), style: 'left:' + o.x + '%;top:' + o.y + '%', pick: () => set({ focus: o.id }) }));
    const focus = fo ? { on: true, off: false, name: fo.name, where: fo.city + ', ' + (fo.coS || fo.co), price: 'от ' + price(fo, usd), href: hrefOf(fo), sel: !!selSet[fo.id], pickT: selSet[fo.id] ? 'Выбрано' : 'Выбрать', toggle: toggle(fo.id) } : { on: false, off: true };
    /* окно «В какую подборку» */
    const COLL = [
      { id: 'c1', title: 'Квартира у моря, Дубай', sub: 'Для Дмитрия Орлова, объектов: 3' },
      { id: 'c2', title: 'Дом с садом, Лимассол', sub: 'Для Сергея Лукина, объектов: 4' },
      { id: 'c3', title: 'Квартира с видом, Дубай', sub: 'Для Павла Киселёва, объектов: 4' }
    ];
    const pickList = COLL.map((c) => ({ title: c.title, sub: c.sub, on: S.pickId === c.id, cls: S.pickId === c.id ? 'is-on' : '', pick: () => set({ pickId: c.id, newOn: false, pickErr: false }) }));
    const selNames = S.sel.map((i) => D.filter((o) => o.id === i)[0].name);
    const submitPick = () => {
      if (S.newOn) {
        if (!S.newTitle.trim() || !S.newClient.trim()) { set({ eT: !S.newTitle.trim(), eC: !S.newClient.trim() }); return; }
        const n = S.sel.length, tt = S.newTitle.trim();
        set({ pickOpen: false, sel: [], newOn: false, newTitle: '', newClient: '', eT: false, eC: false });
        this.say('Создана подборка «' + tt + '», объектов: ' + n);
        return;
      }
      const c = COLL.filter((x) => x.id === S.pickId)[0];
      if (!c) { set({ pickErr: true }); return; }
      set({ pickOpen: false, sel: [], pickId: '' });
      this.say('Добавлено в «' + c.title + '»');
    };
    const hasSel = S.sel.length > 0;
    return {
      q: S.q, onQ: (e) => set({ q: e.target.value, more: false }), noop: () => {},
      selects: selects, anyOpen: S.open !== '', closeSel: () => set({ open: '' }), chips: chips, dirty: dirty,
      reset: () => set({ q: '', country: '', share: '', sort: '', cur: '', sea: false, ready: false, more: false }),
      foundT: 'Найдено объектов: ' + list.length, allLabel: (list.length > 0 && list.every((o) => selSet[o.id])) ? 'Снять выбор со всех' : 'Выбрать все найденные',
      toggleAll: () => { const all = list.every((o) => selSet[o.id]); set({ sel: all ? S.sel.filter((i) => !list.some((o) => o.id === i)) : Array.from(new Set(S.sel.concat(list.map((o) => o.id)))) }); },
      isList: S.view === 'list', isMap: S.view === 'map', listOn: S.view === 'list', mapOn: S.view === 'map', showList: () => set({ view: 'list' }), showMap: () => set({ view: 'map' }),
      curNote: usd, empty: list.length === 0, cards: S.view === 'list' ? cards : [], pins: pins, focus: focus,
      canMore: S.view === 'list' && list.length > 6 && !S.more, moreLabel: 'Показать ещё: ' + (list.length - 6), showMore: () => set({ more: true }),
      hasSel: hasSel, noSel: !hasSel, selN: S.sel.length, selNames: selNames.join(', ') + '.', mainLabel: 'Добавить в подборку (' + S.sel.length + ')',
      clearSel: () => set({ sel: [] }), openPick: () => set({ pickOpen: true, pickErr: false }), closePick: () => set({ pickOpen: false }),
      pickOpen: S.pickOpen, pickList: pickList, newOn: S.newOn, newOnB: S.newOn, newCls: S.newOn ? 'is-on' : '', pickNew: () => set({ newOn: true, pickId: '', pickErr: false }),
      newTitle: S.newTitle, newClient: S.newClient, onNewTitle: (e) => set({ newTitle: e.target.value, eT: false }), onNewClient: (e) => set({ newClient: e.target.value, eC: false }),
      titleCls: S.eT ? 'is-err' : '', clientCls: S.eC ? 'is-err' : '', pickErr: S.pickErr, pickBtn: S.newOn ? 'Создать и добавить' : 'Добавить', submitPick: submitPick,
      helpOpen: S.helpOpen, toggleHelp: () => set({ helpOpen: !S.helpOpen }),
      whyName: (D.filter((x) => x.id === S.whyId)[0] || {}).name || '', whyRows: WR, whyOpen: S.whyOpen, openWhy: () => set({ whyOpen: true }), closeWhy: () => set({ whyOpen: false }),
      toastOn: !!S.toast, toast: S.toast, closeToast: () => set({ toast: '' })
    };
  }
}
